package hlc

type HybridLogicalClock struct {
    physicalTime int64
    logicalCount int32
}

// Updates clock state on message receive
func (c *HybridLogicalClock) Update(msgPhysical int64, msgLogical int32) {
    now := getPhysicalTime()
    if now > c.physicalTime && now > msgPhysical {
        c.physicalTime = now
        c.logicalCount = 0
    } else {
        maxPhysical := max(c.physicalTime, msgPhysical)
        c.physicalTime = maxPhysical
        c.logicalCount++
    }
}
